const std=@import("std");
fn store(x:i64,out:[]u8)void{const u:u64=@bitCast(x);for(0..8)|b|out[b]=@truncate(u>>@intCast(8*b));}
export fn midpoint_integration(input:?[*]const i64,length:usize,output:?[*]u8,capacity:usize)i64{if(input==null or length!=4)return -1;const v=input.?[0..4];const f=v[0];const steps=v[1];const aa=v[2];const bb=v[3];if(f<0 or f>2 or steps<1 or steps>256 or aa< -1_000_000 or aa>1_000_000 or bb<aa or bb>1_000_000)return -1;if(output==null or capacity<8)return -2;const a=@as(f64,@floatFromInt(aa))/1e6;const b=@as(f64,@floatFromInt(bb))/1e6;const h=(b-a)/@as(f64,@floatFromInt(steps));var sum:f64=0;for(0..@intCast(steps))|i|{const x=a+@as(f64,@floatFromInt(i))*h+h/2;const y:f64=if(f==0)1 else if(f==1)x else x*x;sum+=y;}const value:i64=@intFromFloat(@floor(h*sum*1e9+0.5));store(value,output.?[0..8]);return 8;}
